-1	Most Common Likers	Which users like particular other users the most?	WITH pairs AS (\n    SELECT p.user_id liked, pa.user_id liker\n    FROM post_actions pa\n    LEFT JOIN posts p ON p.id = pa.post_id\n    WHERE post_action_type_id = 2\n)\nSELECT liker liker_user_id, liked liked_user_id, count(*)\nFROM pairs\nGROUP BY liked, liker\nORDER BY count DESC\n	-1	\N	f	2026-11-21 23:57:42.160399	2026-11-21 23:57:42.160399
