-3	Last 500 posts that were edited by TL0/TL1 users	fighting human-driven copy-paste spam	SELECT\n    p.id AS post_id,\n    topic_id\nFROM posts p\n    JOIN users u\n        ON u.id = p.user_id\n    JOIN topics t\n        ON t.id = p.topic_id\nWHERE p.last_editor_id = p.user_id\n    AND p.self_edits > 0\n    AND (u.trust_level = 0 OR u.trust_level = 1)\n    AND p.deleted_at IS NULL\n    AND t.deleted_at IS NULL\n    AND t.archetype = 'regular'\nORDER BY p.updated_at DESC\nLIMIT 500\n	-1	\N	f	2026-11-21 23:57:42.16523	2026-11-21 23:57:42.16523
-4	New Topics by Category	Lists all new topics ordered by category and creation_date. The query accepts a ‘months_ago’ parameter. It defaults to 0 to give you the stats for the current month.	-- [params]\n-- int :months_ago = 1\n\nWITH query_period as (\n    SELECT\n        date_trunc('month', CURRENT_DATE) - :months_ago * INTERVAL '1 month' as period_start,\n        date_trunc('month', CURRENT_DATE) - :months_ago * INTERVAL '1 month' + INTERVAL '1 month' - INTERVAL '1 second' as period_end\n)\n\nSELECT\n    t.id as topic_id,\n    t.category_id\nFROM topics t\nRIGHT JOIN query_period qp\n    ON t.created_at >= qp.period_start\n        AND t.created_at <= qp.period_end\nWHERE t.user_id > 0\n    AND t.category_id IS NOT NULL\nORDER BY t.category_id, t.created_at DESC\n	-1	\N	f	2026-11-21 23:57:42.167131	2026-11-21 23:57:42.167131
-5	Top 100 Active Topics	based on the number of replies, it accepts a ‘months_ago’ parameter, defaults to 1 to give results for the last calendar month.	-- [params]\n-- int :months_ago = 1\n\nWITH query_period AS\n(SELECT date_trunc('month', CURRENT_DATE) - :months_ago * INTERVAL '1 month' AS period_start,\n                                                    date_trunc('month', CURRENT_DATE) - :months_ago * INTERVAL '1 month' + INTERVAL '1 month' - INTERVAL '1 second' AS period_end)\nSELECT t.id AS topic_id,\n    t.category_id,\n    COUNT(p.id) AS reply_count\nFROM topics t\nJOIN posts p ON t.id = p.topic_id\nJOIN query_period qp ON p.created_at >= qp.period_start\nAND p.created_at <= qp.period_end\nWHERE t.archetype = 'regular'\nAND t.user_id > 0\nGROUP BY t.id\nORDER BY COUNT(p.id) DESC, t.score DESC\nLIMIT 100\n	-1	\N	f	2026-11-21 23:57:42.169163	2026-11-21 23:57:42.169163
-6	Top 100 Likers	returns the top 100 likers for a given monthly period ordered by like_count. It accepts a ‘months_ago’ parameter, defaults to 1 to give results for the last calendar month.	-- [params]\n-- int :months_ago = 1\n\nWITH query_period AS (\n    SELECT\n        date_trunc('month', CURRENT_DATE) - :months_ago * INTERVAL '1 month' as period_start,\n        date_trunc('month', CURRENT_DATE) - :months_ago * INTERVAL '1 month' + INTERVAL '1 month' - INTERVAL '1 second' as period_end\n        )\n\n    SELECT\n        ua.user_id,\n        count(1) AS like_count\n    FROM user_actions ua\n    INNER JOIN query_period qp\n    ON ua.created_at >= qp.period_start\n    AND ua.created_at <= qp.period_end\n    WHERE ua.action_type = 1\n    GROUP BY ua.user_id\n    ORDER BY like_count DESC\n    LIMIT 100\n	-1	\N	f	2026-11-21 23:57:42.171256	2026-11-21 23:57:42.171256
-7	Top 50 Quality Users	based on post score calculated using reply count, likes, incoming links, bookmarks, time spent and read count.	SELECT sum(p.score) / count(p) AS "average score per post",\n    count(p.id) AS post_count,\n    p.user_id\nFROM posts p\nJOIN users u ON u.id = p.user_id\nWHERE p.created_at >= CURRENT_DATE - INTERVAL '6 month'\nAND NOT u.admin\nAND u.active\nGROUP BY user_id,\n    u.views\nHAVING count(p.id) > 50\nORDER BY sum(p.score) / count(p) DESC\nLIMIT 50\n	-1	\N	f	2026-11-21 23:57:42.17333	2026-11-21 23:57:42.17333
-8	User Participation Statistics	Detailed statistics for the most active users.	-- [params]\n-- int :from_days_ago = 0\n-- int :duration_days = 30\nWITH t AS (\n    SELECT CURRENT_TIMESTAMP - ((:from_days_ago + :duration_days) * (INTERVAL '1 days')) AS START,\n        CURRENT_TIMESTAMP - (:from_days_ago * (INTERVAL '1 days')) AS END\n),\npr AS (\n    SELECT user_id, COUNT(1) AS visits,\n        SUM(posts_read) AS posts_read\n    FROM user_visits, t\n    WHERE posts_read > 0\n        AND visited_at > t.START\n        AND visited_at < t.\n        END\n    GROUP BY\n        user_id\n),\npc AS (\n    SELECT p.user_id, COUNT(1) AS posts_created\n    FROM posts p\n    JOIN t ON p.created_at > t.START AND p.created_at < t.END\n    JOIN pr ON p.user_id = pr.user_id\n    GROUP BY\n        p.user_id\n),\nttopics AS (\n    SELECT topics.user_id, topics.posts_count\n    FROM topics\n    JOIN t ON topics.created_at > t.START AND topics.created_at < t.END\n    JOIN pr ON topics.user_id = pr.user_id\n),\ntc AS (\n    SELECT user_id, COUNT(1) AS topics_created\n    FROM ttopics\n    GROUP BY user_id\n),\ntwr AS (\n    SELECT user_id, COUNT(1) AS topics_with_replies\n    FROM ttopics\n    WHERE posts_count > 1\n    GROUP BY user_id\n),\ntv AS (\n    SELECT topic_views.user_id,\n        COUNT(DISTINCT(topic_views.topic_id)) AS topics_viewed\n    FROM topic_views\n    JOIN t ON topic_views.viewed_at > t.START AND topic_views.viewed_at < t.END\n    JOIN pr ON topic_views.user_id = pr.user_id\n    WHERE topic_views.user_id IS NOT NULL\n    GROUP BY topic_views.user_id\n),\nlikes AS (\n    SELECT post_actions.user_id AS given_by_user_id,\n        posts.user_id AS received_by_user_id\n    FROM post_actions\n    JOIN t ON post_actions.created_at > t.START AND post_actions.created_at < t.END\n    LEFT JOIN posts ON post_actions.post_id = posts.id\n    WHERE\n        post_action_type_id = 2\n        AND (\n            post_actions.user_id IN (SELECT user_id FROM pr)\n            OR posts.user_id IN (SELECT user_id FROM pr)\n        )\n),\nlg AS (\n    SELECT given_by_user_id AS user_id,\n        COUNT(1) AS likes_given\n    FROM likes\n    GROUP BY user_id\n),\nlr AS (\n    SELECT received_by_user_id AS user_id,\n        COUNT(1) AS likes_received\n    FROM likes\n    GROUP BY user_id\n)\nSELECT\n    pr.user_id,\n    username,\n    name,\n    email,\n    visits,\n    COALESCE(topics_viewed, 0) AS topics_viewed,\n    COALESCE(posts_read, 0) AS posts_read,\n    COALESCE(posts_created, 0) AS posts_created,\n    COALESCE(topics_created, 0) AS topics_created,\n    COALESCE(topics_with_replies, 0) AS topics_with_replies,\n    COALESCE(likes_given, 0) AS likes_given,\n    COALESCE(likes_received, 0) AS likes_received\nFROM pr\nLEFT JOIN tv USING (user_id)\nLEFT JOIN pc USING (user_id)\nLEFT JOIN tc USING (user_id)\nLEFT JOIN twr USING (user_id)\nLEFT JOIN lg USING (user_id)\nLEFT JOIN lr USING (user_id)\nLEFT JOIN user_emails e ON e.user_id = pr.user_id AND e.PRIMARY = TRUE\nLEFT JOIN users ON pr.user_id = users.id\nORDER BY\n    visits DESC,\n    posts_read DESC,\n    posts_created DESC\n	-1	\N	f	2026-11-21 23:57:42.175222	2026-11-21 23:57:42.175222
-9	Top 50 Largest Uploads	sorted by file size.	SELECT posts.id AS post_id,\n    uploads.original_filename,\n    ROUND(uploads.filesize / 1000000.0, 2) AS size_in_mb,\n    uploads.extension,\n    uploads.created_at,\n    uploads.url\nFROM upload_references\nJOIN uploads ON uploads.id = upload_references.upload_id\nJOIN posts ON posts.id = upload_references.target_id AND upload_references.target_type = 'Post'\nORDER BY uploads.filesize DESC\nLIMIT 50\n	-1	\N	f	2026-11-21 23:57:42.177165	2026-11-21 23:57:42.177165
