-11	Most Active Lurkers	active users without posts and excessive read times, it accepts a post_read_count parameter that sets the threshold for posts read.	-- [params]\n-- int :post_read_count = 100\nWITH posts_by_user AS (\n    SELECT COUNT(*) AS posts, user_id\n    FROM posts\n    GROUP BY user_id\n), posts_read_by_user AS (\n    SELECT SUM(posts_read) AS posts_read, user_id\n    FROM user_visits\n    GROUP BY user_id\n)\nSELECT\n    u.id,\n    u.username_lower AS "username",\n    u.created_at,\n    u.last_seen_at,\n    COALESCE(pbu.posts, 0) AS "posts_created",\n    COALESCE(prbu.posts_read, 0) AS "posts_read"\nFROM users u\nLEFT JOIN posts_by_user pbu ON pbu.user_id = u.id\nLEFT JOIN posts_read_by_user prbu ON prbu.user_id = u.id\nWHERE u.active = true\nAND posts IS NULL\nAND posts_read > :post_read_count\nORDER BY u.id\n	-1	\N	f	2026-11-21 23:57:42.181176	2026-11-21 23:57:42.181176
