-14	Group Members Reply Count	Number of replies by members of a group over a given time period. Requires 'group_name', 'start_date', and 'end_date' parameters. Dates need to be in the form 'yyyy-mm-dd'. Accepts an 'include_pms' parameter.	-- [params]\n-- date :start_date\n-- date :end_date\n-- string :group_name\n-- boolean :include_pms = false\n\nWITH target_users AS (\nSELECT\nu.id AS user_id\nFROM users u\nJOIN group_users gu\nON gu.user_id = u.id\nJOIN groups g\nON g.id = gu.group_id\nWHERE g.name = :group_name\nAND gu.created_at::date <= :end_date\n),\ntarget_posts AS (\nSELECT\np.id,\np.user_id\nFROM posts p\nJOIN topics t\nON t.id = p.topic_id\nWHERE CASE WHEN :include_pms THEN true ELSE t.archetype = 'regular' END\nAND t.deleted_at IS NULL\nAND p.deleted_at IS NULL\nAND p.created_at::date >= :start_date\nAND p.created_at::date <= :end_date\nAND p.post_number > 1\n)\n\nSELECT\ntu.user_id,\nCOALESCE(COUNT(tp.id), 0) AS reply_count\nFROM target_users tu\nLEFT OUTER JOIN target_posts tp\nON tp.user_id = tu.user_id\nGROUP BY tu.user_id\nORDER BY reply_count DESC, tu.user_id\n	-1	\N	f	2026-11-21 23:57:42.187469	2026-11-21 23:57:42.187469
