-16	Poll results report	Details of a poll result, including details about each vote and voter, useful for analyzing results in external software.	-- [params]\n-- string :poll_name\n-- int :post_id\n\nSELECT\n  poll_votes.updated_at AS vote_time,\n  poll_votes.poll_option_id AS vote_option,\n  users.id AS user_id,\n  users.username,\n  users.name,\n  users.trust_level,\n  poll_options.html AS vote_option_full\nFROM\n  poll_votes\nINNER JOIN\n  polls ON polls.id = poll_votes.poll_id\nINNER JOIN\n  users ON users.id = poll_votes.user_id\nINNER JOIN\n  poll_options ON poll_votes.poll_id = poll_options.poll_id AND poll_votes.poll_option_id = poll_options.id\nWHERE\n  polls.name = :poll_name AND\n  polls.post_id = :post_id\n	-1	\N	f	2026-11-21 23:57:42.205339	2026-11-21 23:57:42.205339
-17	Top tags per year	List the top tags per year.	-- [params]\n-- integer :rank_max = 5\n\nWITH data AS (SELECT\n    tag_id,\n    EXTRACT(YEAR FROM created_at) AS year\nFROM topic_tags)\n\nSELECT year, rank, name, qt FROM (\n    SELECT\n  tag_id,\n  COUNT(tag_id) AS qt,\n  year,\n  rank() OVER (PARTITION BY year ORDER BY COUNT(tag_id) DESC) AS rank\n    FROM\n  data\n    GROUP BY year, tag_id) as rnk\nINNER JOIN tags ON tags.id = rnk.tag_id\nWHERE rank <= :rank_max\nORDER BY year DESC, qt DESC\n	-1	\N	f	2026-11-21 23:57:42.208327	2026-11-21 23:57:42.208327
-18	Number of replies by category	List the number of replies by category.	-- [params]\n-- boolean :enable_null_category = false\n\nWITH post AS (SELECT\n    id AS post_id,\n    topic_id,\n    EXTRACT(YEAR FROM created_at) AS year\nFROM posts\nWHERE post_type = 1\n    AND deleted_at ISNULL\n    AND post_number != 1)\n\nSELECT\n    p.year,\n    t.category_id AS id,\n    c.name category,\n    COUNT(p.post_id) AS qt\nFROM post p\nINNER JOIN topics t ON t.id = p.topic_id\nLEFT JOIN categories c ON c.id = t.category_id\nWHERE t.deleted_at ISNULL\n    AND (:enable_null_category = true OR t.category_id NOTNULL)\nGROUP BY t.category_id, c.name, p.year\nORDER BY p.year DESC, qt DESC\n	-1	\N	f	2026-11-21 23:57:42.210686	2026-11-21 23:57:42.210686
-19	Poll results report (for Ranked Choice polls)	Details of a Ranked Choice poll result, including details about each vote and voter inc. rank, useful for analyzing results in external software.	-- [params]\n-- string :poll_name\n-- int :post_id\n\n  SELECT\n    poll_votes.updated_at AS vote_time,\n    poll_votes.poll_option_id AS vote_option,\n    poll_votes.rank AS vote_rank,\n    users.id AS user_id,\n    users.username,\n    users.name,\n    users.trust_level,\n    poll_options.html AS vote_option_full\n  FROM\n    poll_votes\n  INNER JOIN\n    polls ON polls.id = poll_votes.poll_id\n  INNER JOIN\n    users ON users.id = poll_votes.user_id\n  INNER JOIN\n    poll_options ON poll_votes.poll_id = poll_options.poll_id AND poll_votes.poll_option_id = poll_options.id\n  WHERE\n    polls.name = :poll_name AND\n    polls.post_id = :post_id\n	-1	\N	f	2026-11-21 23:57:42.213446	2026-11-21 23:57:42.213446
-20	Weekly Unique Visitors	Number of distinct users who visited the site each week. Accepts a 'weeks_ago' parameter, defaults to the last 12 weeks.	-- [params]\n-- int :weeks_ago = 12\n\nSELECT\n    DATE_TRUNC('week', visited_at)::date AS week,\n    COUNT(DISTINCT user_id) AS active_users\nFROM user_visits\nWHERE visited_at >= CURRENT_DATE - (:weeks_ago * INTERVAL '1 week')\nGROUP BY week\nORDER BY week\n	-1	\N	f	2026-11-21 23:57:42.21579	2026-11-21 23:57:42.21579
-21	Top 100 Topics by Views	The most viewed topics in a recent period, split into anonymous and logged-in views. Accepts a 'days_ago' parameter, defaults to the last 7 days.	-- [params]\n-- int :days_ago = 7\n\nSELECT\n    t.id AS topic_id,\n    t.category_id,\n    COALESCE(SUM(tvs.anonymous_views), 0) AS anonymous_views,\n    COALESCE(SUM(tvs.logged_in_views), 0) AS logged_in_views,\n    COALESCE(SUM(tvs.anonymous_views + tvs.logged_in_views), 0) AS total_views\nFROM topics t\nJOIN topic_view_stats tvs ON tvs.topic_id = t.id\n    AND tvs.viewed_at >= CURRENT_DATE - CAST(:days_ago AS integer)\nWHERE t.deleted_at IS NULL\n    AND t.archetype = 'regular'\nGROUP BY t.id, t.category_id\nORDER BY total_views DESC\nLIMIT 100\n	-1	\N	f	2026-11-21 23:57:42.218371	2026-11-21 23:57:42.218371
-22	Top 200 Search Terms	The most popular search terms by number of distinct users searching for them, useful for spotting content gaps. Accepts a 'days_ago' parameter, defaults to the last 30 days.	-- [params]\n-- int :days_ago = 30\n\nSELECT\n    term,\n    COUNT(*) AS searches,\n    COUNT(DISTINCT user_id) AS distinct_users\nFROM search_logs\nWHERE created_at >= CURRENT_DATE - CAST(:days_ago AS integer)\nGROUP BY term\nORDER BY distinct_users DESC, searches DESC\nLIMIT 200\n	-1	\N	f	2026-11-21 23:57:42.220666	2026-11-21 23:57:42.220666
-23	Topic Views and Link Clicks Over Time	Daily views (anonymous and logged in) and outbound link clicks for a single topic, useful for measuring how an announcement performed. Requires a 'topic_id' parameter, accepts a 'days_ago' parameter.	-- [params]\n-- topic_id :topic_id\n-- int :days_ago = 30\n\n-- gapless day series, so days with zero activity still show up as rows\nWITH day_series AS (\n    SELECT generate_series(\n        CURRENT_DATE - CAST(:days_ago AS integer),\n        CURRENT_DATE,\n        '1 day'::interval\n    )::date AS day\n),\ndaily_clicks AS (\n    SELECT\n        tlc.created_at::date AS day,\n        COUNT(*) AS link_clicks\n    FROM topic_link_clicks tlc\n    JOIN topic_links tl ON tl.id = tlc.topic_link_id\n    WHERE tl.topic_id = :topic_id\n        AND tlc.created_at >= CURRENT_DATE - CAST(:days_ago AS integer)\n    GROUP BY tlc.created_at::date\n),\ndaily_views AS (\n    SELECT\n        viewed_at AS day,\n        COALESCE(SUM(anonymous_views), 0) AS anonymous_views,\n        COALESCE(SUM(logged_in_views), 0) AS logged_in_views\n    FROM topic_view_stats\n    WHERE topic_id = :topic_id\n        AND viewed_at >= CURRENT_DATE - CAST(:days_ago AS integer)\n    GROUP BY viewed_at\n)\nSELECT\n    ds.day,\n    COALESCE(dv.anonymous_views, 0) + COALESCE(dv.logged_in_views, 0) AS total_views,\n    COALESCE(dv.anonymous_views, 0) AS anonymous_views,\n    COALESCE(dv.logged_in_views, 0) AS logged_in_views,\n    COALESCE(dc.link_clicks, 0) AS link_clicks\nFROM day_series ds\nLEFT JOIN daily_views dv ON dv.day = ds.day\nLEFT JOIN daily_clicks dc ON dc.day = ds.day\nORDER BY ds.day\n	-1	\N	f	2026-11-21 23:57:42.223411	2026-11-21 23:57:42.223411
-24	Average Time to First Response	Average number of hours before a new topic receives its first reply from someone other than the topic author, grouped by week. Accepts a 'weeks_ago' parameter, defaults to the last 12 weeks.	-- [params]\n-- int :weeks_ago = 12\n\nSELECT\n    week,\n    ROUND(AVG(hours_to_response)::numeric, 1) AS avg_hours_to_first_response\nFROM (\n    SELECT\n        DATE_TRUNC('week', t.created_at)::date AS week,\n        EXTRACT(EPOCH FROM MIN(p.created_at) - t.created_at) / 3600.0 AS hours_to_response\n    FROM topics t\n    JOIN posts p ON p.topic_id = t.id\n    WHERE t.created_at >= CURRENT_DATE - (:weeks_ago * INTERVAL '1 week')\n        AND t.archetype = 'regular'\n        AND t.deleted_at IS NULL\n        AND p.deleted_at IS NULL\n        AND p.post_number > 1\n        AND p.user_id <> t.user_id\n        AND p.post_type = 1\n    GROUP BY t.id, week\n) per_topic\nGROUP BY week\nORDER BY week\n	-1	\N	f	2026-11-21 23:57:42.226385	2026-11-21 23:57:42.226385
-25	New Topic Response Rate	Percentage of new public topics that receive any reply, and a staff reply, within 30 days of creation, grouped by month. Only counts topics old enough to have had a fair chance at a reply. Accepts a 'months_ago' parameter.	-- [params]\n-- int :months_ago = 6\n\nWITH base_topics AS (\n    SELECT\n        t.id,\n        t.created_at,\n        date_trunc('month', t.created_at)::date AS month\n    FROM topics t\n    LEFT JOIN categories c ON c.id = t.category_id\n    WHERE t.created_at >= date_trunc('month', CURRENT_DATE) - (:months_ago * INTERVAL '1 month')\n        -- only count topics old enough to have had the full 30-day reply window\n        AND t.created_at < CURRENT_DATE - INTERVAL '30 days'\n        AND t.deleted_at IS NULL\n        AND t.archetype = 'regular'\n        AND COALESCE(c.read_restricted, false) = false\n        AND t.user_id > 0\n),\ntopic_responses AS (\n    SELECT\n        bt.month,\n        EXISTS (\n            SELECT 1\n            FROM posts p\n            WHERE p.topic_id = bt.id\n                AND p.post_number > 1\n                AND p.post_type = 1\n                AND p.deleted_at IS NULL\n                AND p.created_at <= bt.created_at + INTERVAL '30 days'\n        ) AS has_any_reply,\n        EXISTS (\n            SELECT 1\n            FROM posts p\n            JOIN users u ON u.id = p.user_id\n            WHERE p.topic_id = bt.id\n                AND p.post_number > 1\n                AND p.post_type = 1\n                AND p.deleted_at IS NULL\n                AND p.created_at <= bt.created_at + INTERVAL '30 days'\n                AND (u.admin OR u.moderator)\n        ) AS has_staff_reply\n    FROM base_topics bt\n)\nSELECT\n    month,\n    ROUND(100.0 * COUNT(*) FILTER (WHERE has_any_reply) / COUNT(*), 1) AS any_reply_pct,\n    ROUND(100.0 * COUNT(*) FILTER (WHERE has_staff_reply) / COUNT(*), 1) AS staff_reply_pct\nFROM topic_responses\nGROUP BY month\nORDER BY month\n	-1	\N	f	2026-11-21 23:57:42.229471	2026-11-21 23:57:42.229471
-26	Community Participation Trend	Monthly count of distinct non-staff users replying in public topics, with average replies per replier, useful to distinguish 'fewer people participating' from 'the same people posting less'. Accepts a 'months_ago' parameter.	-- [params]\n-- int :months_ago = 6\n\nWITH monthly AS (\n    SELECT\n        date_trunc('month', p.created_at)::date AS month,\n        COUNT(*) AS replies,\n        COUNT(DISTINCT p.user_id) AS distinct_repliers\n    FROM posts p\n    JOIN topics t ON t.id = p.topic_id\n    JOIN users u ON u.id = p.user_id\n    LEFT JOIN categories c ON c.id = t.category_id\n    WHERE p.created_at >= date_trunc('month', CURRENT_DATE) - (:months_ago * INTERVAL '1 month')\n        AND p.deleted_at IS NULL\n        AND p.post_type = 1\n        AND p.post_number > 1\n        AND t.deleted_at IS NULL\n        AND t.archetype = 'regular'\n        AND COALESCE(c.read_restricted, false) = false\n        AND u.id > 0\n        AND NOT u.admin\n        AND NOT u.moderator\n    GROUP BY 1\n)\nSELECT\n    month,\n    distinct_repliers,\n    ROUND(replies::numeric / NULLIF(distinct_repliers, 0), 2) AS replies_per_person\nFROM monthly\nORDER BY month\n	-1	\N	f	2026-11-21 23:57:42.231752	2026-11-21 23:57:42.231752
-27	Trust Level Growth Summary	Number of users who reached each trust level in a recent period, alongside the current total population at each level. Accepts a 'days_ago' parameter, defaults to the last 28 days.	-- [params]\n-- int :days_ago = 28\n\n-- new signups with no recorded trust level change are still at trust level 0\nWITH trust_level_0_users AS (\n    SELECT\n        0 AS trust_level,\n        COUNT(*) AS users_gained\n    FROM users u\n    LEFT JOIN (\n        SELECT DISTINCT target_user_id\n        FROM user_histories\n        WHERE created_at >= CURRENT_DATE - CAST(:days_ago AS integer)\n            AND action IN (2, 15) -- change_trust_level, auto_trust_level_change\n    ) tlc ON u.id = tlc.target_user_id\n    WHERE u.created_at >= CURRENT_DATE - CAST(:days_ago AS integer)\n        AND tlc.target_user_id IS NULL\n),\ntrust_level_changes AS (\n    SELECT\n        uh.new_value::int AS trust_level,\n        COUNT(DISTINCT uh.target_user_id) AS users_gained\n    FROM user_histories uh\n    JOIN users u ON uh.target_user_id = u.id\n    WHERE uh.created_at >= CURRENT_DATE - CAST(:days_ago AS integer)\n        AND uh.action IN (2, 15) -- change_trust_level, auto_trust_level_change\n        AND uh.new_value IN ('1', '2', '3', '4')\n    GROUP BY uh.new_value\n),\ntrust_levels_combined AS (\n    SELECT generate_series(0, 4) AS trust_level\n)\nSELECT\n    t.trust_level,\n    CASE\n        WHEN t.trust_level = 0 THEN COALESCE(tl0.users_gained, 0)\n        ELSE COALESCE(tlc.users_gained, 0)\n    END AS users_gained_recently,\n    (SELECT COUNT(*) FROM users WHERE trust_level = t.trust_level) AS total_users_at_level\nFROM trust_levels_combined t\nLEFT JOIN trust_level_changes tlc ON t.trust_level = tlc.trust_level\nLEFT JOIN trust_level_0_users tl0 ON t.trust_level = 0\nORDER BY t.trust_level\n	-1	\N	f	2026-11-21 23:57:42.23486	2026-11-21 23:57:42.23486
-28	Topics With No Response	Number of topics per period that never received a reply from anyone other than the topic author. Accepts 'days_ago', 'category_id', 'include_subcategories' and 'interval' (day, week, month or year) parameters.	-- [params]\n-- int :days_ago = 90\n-- null category_id :category_id\n-- boolean :include_subcategories = false\n-- string :interval = day\n\nWITH no_response_topics AS (\n    SELECT * FROM (\n        SELECT t.id, t.created_at, MIN(p.post_number) AS first_reply\n        FROM topics t\n        -- reply conditions live in the join, so topics with no replies\n        -- survive with first_reply NULL instead of being filtered out\n        LEFT JOIN posts p ON p.topic_id = t.id\n            AND p.user_id <> t.user_id\n            AND p.deleted_at IS NULL\n            AND p.post_type = 1\n        WHERE t.archetype = 'regular'\n            AND t.deleted_at IS NULL\n            AND t.created_at >= CURRENT_DATE - CAST(:days_ago AS integer)\n            AND (\n                CAST(:category_id AS integer) IS NULL\n                OR t.category_id = :category_id\n                OR (:include_subcategories AND t.category_id IN (\n                    SELECT id FROM categories WHERE parent_category_id = :category_id\n                ))\n            )\n        GROUP BY t.id\n    ) tt\n    WHERE tt.first_reply IS NULL OR tt.first_reply < 2\n)\nSELECT\n    date_trunc(:interval, created_at)::date AS period,\n    COUNT(id) AS topics_without_response\nFROM no_response_topics\nGROUP BY period\nORDER BY period\n	-1	\N	f	2026-11-21 23:57:42.237499	2026-11-21 23:57:42.237499
-29	Top Posters in a Given Timeframe	Ranks users by topics created and replies posted in a date range. Requires 'start_date' and 'end_date' parameters (yyyy-mm-dd). Accepts a 'top_x' parameter, defaults to 10.	-- [params]\n-- date :start_date\n-- date :end_date\n-- int :top_x = 10\n\nSELECT\n    p.user_id,\n    COUNT(*) AS topics_plus_replies,\n    COUNT(*) FILTER (WHERE p.post_number = 1) AS topics,\n    COUNT(*) FILTER (WHERE p.post_number <> 1) AS replies\nFROM posts p\nJOIN topics t ON t.id = p.topic_id\nWHERE p.created_at::date BETWEEN :start_date AND :end_date\n    AND t.archetype = 'regular'\n    AND p.deleted_at IS NULL\n    AND t.deleted_at IS NULL\n    AND p.post_type = 1\n    AND p.user_id > 0\nGROUP BY p.user_id\nORDER BY topics_plus_replies DESC\nLIMIT :top_x\n	-1	\N	f	2026-11-21 23:57:42.239948	2026-11-21 23:57:42.239948
-30	Category Activity Breakdown	Topic count, post count, likes and reads per category for a date range. Requires 'start_date' and 'end_date' parameters (yyyy-mm-dd).	-- [params]\n-- date :start_date\n-- date :end_date\n\nSELECT\n    c.id AS category_id,\n    COUNT(DISTINCT t.id) AS topics,\n    COUNT(p.id) AS posts,\n    SUM(p.like_count) AS likes,\n    SUM(p.reads) AS reads\nFROM categories c\nJOIN topics t ON t.category_id = c.id\nJOIN posts p ON p.topic_id = t.id AND p.post_type = 1\nWHERE p.created_at::date BETWEEN :start_date AND :end_date\n    AND p.deleted_at IS NULL\n    AND t.deleted_at IS NULL\nGROUP BY c.id\nORDER BY COUNT(p.id) DESC\n	-1	\N	f	2026-11-21 23:57:42.242953	2026-11-21 23:57:42.242953
-31	Trust Level 3 Promotion Progress	Checks every trust level 3 promotion requirement for current trust level 2 users, mirroring the logic of the built-in promotion job, including promotion blockers (locked trust level, active or recent suspensions and silences). Each threshold is a parameter defaulting to the matching site setting's default. Set 'show_all_results' to false to only list users currently meeting every requirement.	-- [params]\n-- int :tl_time_period = 100\n-- int :tl_requires_days_visited = 50\n-- int :tl_requires_topics_replied_to = 10\n-- int :tl_requires_topics_viewed = 25\n-- int :tl_requires_topics_viewed_cap = 500\n-- int :tl_requires_posts_read = 25\n-- int :tl_requires_posts_read_cap = 20000\n-- int :tl_requires_max_flagged = 5\n-- int :tl_requires_topics_viewed_all_time = 200\n-- int :tl_requires_posts_read_all_time = 500\n-- int :tl_requires_likes_given = 30\n-- int :tl_requires_likes_received = 20\n-- boolean :show_all_results = true\n\nWITH tl3_candidates AS (\n    SELECT id AS user_id, manual_locked_trust_level, silenced_till, suspended_till\n    FROM users\n    WHERE trust_level = 2\n    AND last_seen_at >= CURRENT_DATE - (:tl_time_period || ' days')::interval\n),\nmin_topics_viewed AS (\n    SELECT LEAST(COUNT(*) * (:tl_requires_topics_viewed / 100.0), :tl_requires_topics_viewed_cap) AS min_topics_viewed\n    FROM topics\n    WHERE visible = true AND archetype = 'regular'\n        AND created_at >= CURRENT_DATE - (:tl_time_period || ' days')::interval\n),\nmin_posts_read AS (\n    SELECT LEAST(COUNT(*) * (:tl_requires_posts_read / 100.0), :tl_requires_posts_read_cap) AS min_posts_read\n    FROM posts p\n    JOIN topics t ON t.id = p.topic_id\n    WHERE t.deleted_at IS NULL AND t.archetype = 'regular'\n        AND p.deleted_at IS NULL AND p.post_type = 1\n        AND p.created_at >= CURRENT_DATE - (:tl_time_period || ' days')::interval\n),\nmin_likes_received_days AS (\n    SELECT LEAST(:tl_requires_likes_received::float / 3.0, 0.75 * :tl_time_period::float)\n),\ndays_visited AS (\n    SELECT uv.user_id, COUNT(uv.user_id) AS days_visited\n    FROM user_visits uv\n    JOIN tl3_candidates c ON c.user_id = uv.user_id\n    WHERE visited_at > CURRENT_DATE - (:tl_time_period || ' days')::interval AND posts_read > 0\n    GROUP BY uv.user_id\n),\nnum_topics_replied_to AS (\n    SELECT p.user_id, COUNT(DISTINCT p.topic_id) AS topic_reply_count\n    FROM posts p\n    JOIN topics t ON t.id = p.topic_id\n    JOIN tl3_candidates c ON c.user_id = p.user_id\n    WHERE p.user_id <> t.user_id AND t.archetype <> 'private_message'\n        AND p.deleted_at IS NULL AND t.deleted_at IS NULL\n        AND p.created_at >= CURRENT_DATE - (:tl_time_period || ' days')::interval\n    GROUP BY p.user_id\n),\ntopics_viewed AS (\n    SELECT tv.user_id, COUNT(tv.user_id) AS topic_view_count\n    FROM topic_views tv\n    JOIN topics t ON t.id = tv.topic_id\n    JOIN tl3_candidates c ON c.user_id = tv.user_id\n    WHERE t.archetype <> 'private_message'\n        AND viewed_at >= CURRENT_DATE - (:tl_time_period || ' days')::interval\n    GROUP BY tv.user_id\n),\nposts_read AS (\n    SELECT uv.user_id, SUM(posts_read) AS posts_read\n    FROM user_visits uv\n    JOIN tl3_candidates c ON c.user_id = uv.user_id\n    WHERE visited_at >= CURRENT_DATE - (:tl_time_period || ' days')::interval\n    GROUP BY uv.user_id\n),\nnum_flagged_posts AS (\n    SELECT p.user_id, COUNT(DISTINCT pa.post_id) AS num_flagged_posts\n    FROM post_actions pa\n    JOIN posts p ON p.id = pa.post_id\n    JOIN tl3_candidates c ON c.user_id = p.user_id\n    WHERE p.created_at >= CURRENT_DATE - (:tl_time_period || ' days')::interval\n        AND (spam_count > 0 OR inappropriate_count > 0)\n        AND agreed_at IS NOT NULL AND pa.user_id <> p.user_id\n    GROUP BY p.user_id\n),\nnum_flagged_by_users AS (\n    SELECT p.user_id, COUNT(DISTINCT pa.user_id) AS num_flagged_by_users\n    FROM post_actions pa\n    JOIN posts p ON p.id = pa.post_id\n    JOIN tl3_candidates c ON c.user_id = p.user_id\n    WHERE p.created_at >= CURRENT_DATE - (:tl_time_period || ' days')::interval\n        AND (spam_count > 0 OR inappropriate_count > 0)\n        AND agreed_at IS NOT NULL AND pa.user_id <> p.user_id\n    GROUP BY p.user_id\n),\ntopics_viewed_all_time AS (\n    SELECT tv.user_id, COUNT(topic_id) AS topics_viewed_all_time\n    FROM topic_views tv\n    JOIN topics t ON t.id = tv.topic_id\n    JOIN tl3_candidates c ON c.user_id = tv.user_id\n    WHERE t.archetype = 'regular'\n    GROUP BY tv.user_id\n),\nposts_read_all_time AS (\n    SELECT uv.user_id, SUM(posts_read) AS posts_read_all_time\n    FROM user_visits uv\n    JOIN tl3_candidates c ON c.user_id = uv.user_id\n    GROUP BY uv.user_id\n),\nnum_likes_given AS (\n    SELECT ua.user_id, COUNT(*) AS num_likes_given\n    FROM user_actions ua\n    JOIN topics t ON t.id = ua.target_topic_id\n    JOIN tl3_candidates c ON c.user_id = ua.user_id\n    WHERE ua.created_at >= CURRENT_DATE - (:tl_time_period || ' days')::interval\n        AND t.archetype = 'regular' AND ua.action_type = 1\n    GROUP BY ua.user_id\n),\nnum_likes_received AS (\n    SELECT ua.user_id, COUNT(*) AS num_likes_received,\n        COUNT(DISTINCT acting_user_id) AS num_likes_received_users,\n        COUNT(DISTINCT ua.created_at::date) AS num_likes_received_days\n    FROM user_actions ua\n    JOIN topics t ON t.id = ua.target_topic_id\n    JOIN tl3_candidates c ON c.user_id = ua.user_id\n    WHERE ua.created_at >= CURRENT_DATE - (:tl_time_period || ' days')::interval\n        AND t.archetype = 'regular' AND ua.action_type = 2\n    GROUP BY ua.user_id\n),\npenalty_counts AS (\n    -- silences/suspensions in the last 6 months (FORGIVENESS_PERIOD) block promotion,\n    -- but a staff-issued unsilence/unsuspend forgives them (a system-issued one does not)\n    SELECT\n        uh.target_user_id AS user_id,\n        SUM(\n            CASE\n                WHEN uh.action = 30 THEN 1 -- silence_user\n                WHEN uh.action = 31 AND uh.acting_user_id <> -1 THEN -1 -- unsilence_user\n                WHEN uh.action = 10 THEN 1 -- suspend_user\n                WHEN uh.action = 11 AND uh.acting_user_id <> -1 THEN -1 -- unsuspend_user\n                ELSE 0\n            END\n        ) AS penalty_count\n    FROM user_histories uh\n    JOIN tl3_candidates c ON c.user_id = uh.target_user_id\n    WHERE uh.action IN (10, 11, 30, 31)\n        AND uh.created_at > NOW() - INTERVAL '6 months'\n    GROUP BY uh.target_user_id\n),\ncandidate_results AS (\n    SELECT\n        c.user_id,\n        c.manual_locked_trust_level IS NULL AS trust_level_unlocked_criteria_met,\n        (c.suspended_till IS NULL OR c.suspended_till <= CURRENT_TIMESTAMP)\n            AND (c.silenced_till IS NULL OR c.silenced_till <= CURRENT_TIMESTAMP) AS not_penalized_criteria_met,\n        COALESCE(pc.penalty_count, 0) AS penalty_count,\n        COALESCE(pc.penalty_count, 0) <= 0 AS penalty_history_criteria_met,\n        COALESCE(days_visited, 0) AS days_visited,\n        COALESCE(days_visited, 0) >= :tl_requires_days_visited AS visits_criteria_met,\n        COALESCE(topic_reply_count, 0) AS topic_reply_count,\n        COALESCE(topic_reply_count, 0) >= :tl_requires_topics_replied_to AS replies_criteria_met,\n        COALESCE(topic_view_count, 0) AS topic_view_count,\n        COALESCE(topic_view_count, 0) >= (SELECT * FROM min_topics_viewed) AS topic_views_criteria_met,\n        COALESCE(posts_read, 0) AS posts_read,\n        COALESCE(posts_read, 0) >= (SELECT * FROM min_posts_read) AS posts_read_criteria_met,\n        COALESCE(num_flagged_posts, 0) AS num_flagged_posts,\n        COALESCE(num_flagged_posts, 0) <= :tl_requires_max_flagged AS flagged_post_criteria_met,\n        COALESCE(num_flagged_by_users, 0) AS num_flagged_by_users,\n        COALESCE(num_flagged_by_users, 0) <= :tl_requires_max_flagged AS flagged_by_users_criteria_met,\n        COALESCE(topics_viewed_all_time, 0) AS topics_viewed_all_time,\n        COALESCE(topics_viewed_all_time, 0) >= :tl_requires_topics_viewed_all_time AS all_time_topic_views_criteria_met,\n        COALESCE(posts_read_all_time, 0) AS posts_read_all_time,\n        COALESCE(posts_read_all_time, 0) >= :tl_requires_posts_read_all_time AS posts_read_all_time_criteria_met,\n        COALESCE(num_likes_given, 0) AS num_likes_given,\n        COALESCE(num_likes_given, 0) >= :tl_requires_likes_given AS likes_given_criteria_met,\n        COALESCE(num_likes_received, 0) AS num_likes_received,\n        COALESCE(num_likes_received, 0) >= :tl_requires_likes_received AS likes_received_criteria_met,\n        COALESCE(num_likes_received_users, 0) AS num_likes_received_users,\n        COALESCE(num_likes_received_users, 0) >= :tl_requires_likes_received::float / 4.0 AS likes_received_users_criteria_met,\n        COALESCE(num_likes_received_days, 0) AS num_likes_received_days,\n        COALESCE(num_likes_received_days, 0) >= (SELECT * FROM min_likes_received_days) AS likes_received_days_criteria_met\n    FROM tl3_candidates c\n    LEFT JOIN days_visited dv ON dv.user_id = c.user_id\n    LEFT JOIN num_topics_replied_to ntr ON ntr.user_id = c.user_id\n    LEFT JOIN topics_viewed tv ON tv.user_id = c.user_id\n    LEFT JOIN posts_read pr ON pr.user_id = c.user_id\n    LEFT JOIN num_flagged_posts nfp ON nfp.user_id = c.user_id\n    LEFT JOIN num_flagged_by_users nfu ON nfu.user_id = c.user_id\n    LEFT JOIN topics_viewed_all_time tvat ON tvat.user_id = c.user_id\n    LEFT JOIN posts_read_all_time prat ON prat.user_id = c.user_id\n    LEFT JOIN num_likes_given nlg ON nlg.user_id = c.user_id\n    LEFT JOIN num_likes_received nlr ON nlr.user_id = c.user_id\n    LEFT JOIN penalty_counts pc ON pc.user_id = c.user_id\n)\nSELECT * FROM candidate_results\nWHERE CASE WHEN :show_all_results THEN true ELSE visits_criteria_met END\n    AND CASE WHEN :show_all_results THEN true ELSE replies_criteria_met END\n    AND CASE WHEN :show_all_results THEN true ELSE topic_views_criteria_met END\n    AND CASE WHEN :show_all_results THEN true ELSE posts_read_criteria_met END\n    AND CASE WHEN :show_all_results THEN true ELSE flagged_post_criteria_met END\n    AND CASE WHEN :show_all_results THEN true ELSE flagged_by_users_criteria_met END\n    AND CASE WHEN :show_all_results THEN true ELSE all_time_topic_views_criteria_met END\n    AND CASE WHEN :show_all_results THEN true ELSE posts_read_all_time_criteria_met END\n    AND CASE WHEN :show_all_results THEN true ELSE likes_given_criteria_met END\n    AND CASE WHEN :show_all_results THEN true ELSE likes_received_criteria_met END\n    AND CASE WHEN :show_all_results THEN true ELSE likes_received_users_criteria_met END\n    AND CASE WHEN :show_all_results THEN true ELSE likes_received_days_criteria_met END\n    AND CASE WHEN :show_all_results THEN true ELSE trust_level_unlocked_criteria_met END\n    AND CASE WHEN :show_all_results THEN true ELSE not_penalized_criteria_met END\n    AND CASE WHEN :show_all_results THEN true ELSE penalty_history_criteria_met END\nORDER BY days_visited DESC\n	-1	\N	f	2026-11-21 23:57:42.245679	2026-11-21 23:57:42.245679
-32	Silenced Users Report	Currently silenced users, when they were silenced and by whom ('system' for automatic silences). Accepts optional 'start_date', 'end_date' and 'silenced_by' parameters.	-- [params]\n-- null date :start_date\n-- null date :end_date\n-- null string :silenced_by\n\nSELECT\n    silenced_users.id AS user_id,\n    silenced_users.silenced_till AS silenced_till,\n    COALESCE(staff.username, 'system') AS silenced_by,\n    user_histories.created_at AS silenced_at\nFROM users silenced_users\n-- lateral join picks only the most recent silence record per user\nLEFT JOIN LATERAL (\n    SELECT uh.*\n    FROM user_histories uh\n    WHERE uh.target_user_id = silenced_users.id\n        AND uh.action = 30 -- silence_user\n    ORDER BY uh.id DESC\n    LIMIT 1\n) user_histories ON true\nLEFT JOIN users staff\n    ON staff.id = user_histories.acting_user_id\nWHERE silenced_users.silenced_till > CURRENT_TIMESTAMP\n    AND (:start_date IS NULL OR user_histories.created_at >= :start_date)\n    AND (:end_date IS NULL OR user_histories.created_at <= :end_date)\n    AND (\n        :silenced_by IS NULL\n        OR ((:silenced_by = 'system' AND staff.username IS NULL) OR staff.username = :silenced_by)\n    )\nORDER BY user_histories.created_at DESC\n	-1	\N	f	2026-11-21 23:57:42.2486	2026-11-21 23:57:42.2486
-33	Recent Official Warnings	Official warnings issued recently, showing who was warned, who issued the warning, and the related topic. Accepts a 'days_ago' parameter, defaults to the last 28 days.	-- [params]\n-- int :days_ago = 28\n\nSELECT\n    w.user_id AS warned_user_id,\n    w.created_by_id AS warning_creator_user_id,\n    w.topic_id,\n    w.created_at\nFROM user_warnings w\nWHERE w.created_at >= CURRENT_DATE - CAST(:days_ago AS integer)\nORDER BY w.created_at DESC\n	-1	\N	f	2026-11-21 23:57:42.250513	2026-11-21 23:57:42.250513
-34	Users With Most Agreed-Upon Flags	Ranks users by the number of their posts that had a flag agreed with by staff, useful for finding repeat offenders.	SELECT\n    p.user_id,\n    COUNT(DISTINCT pa.post_id) AS flagged_posts,\n    COUNT(*) AS agreed_flags\nFROM post_actions pa\nJOIN posts p ON pa.post_id = p.id\nWHERE pa.agreed_at IS NOT NULL\n    AND p.user_id > 0\nGROUP BY p.user_id\nORDER BY agreed_flags DESC, flagged_posts DESC\nLIMIT 100\n	-1	\N	f	2026-11-21 23:57:42.252722	2026-11-21 23:57:42.252722
-35	Subcategory Permission Audit	Finds subcategories granting a group permission that the parent category does not grant — a permission-hygiene check not surfaced by the admin UI.	SELECT subcategories.* FROM (\n    SELECT\n        category.parent_category_id, category.id AS category_id, category.name AS category_name,\n        category_group.permission_type,\n        groups.name AS group_name, groups.id AS group_id\n    FROM categories category\n    INNER JOIN category_groups category_group ON category_group.category_id = category.id\n    INNER JOIN groups ON groups.id = category_group.group_id\n    WHERE parent_category_id IS NOT NULL\n) subcategories\nLEFT JOIN (\n    SELECT\n        category.id AS category_id, category_group.permission_type,\n        groups.id AS group_id\n    FROM categories category\n    INNER JOIN category_groups category_group ON category_group.category_id = category.id\n    INNER JOIN groups ON groups.id = category_group.group_id\n    WHERE parent_category_id IS NULL\n) parent_categories\n    ON parent_categories.category_id = subcategories.parent_category_id\n    AND parent_categories.group_id = subcategories.group_id\n    AND parent_categories.permission_type = subcategories.permission_type\n-- anti-join: keep only grants with no matching grant on the parent category\nWHERE parent_categories.category_id IS NULL\n	-1	\N	f	2026-11-21 23:57:42.25532	2026-11-21 23:57:42.25532
-36	Reading Participation Histogram	Buckets users by how many posts they read in a given period, from a single post up to 2048+, showing the shape of your reading base (lurkers vs power readers). Accepts 'from_days_ago' and 'duration_days' parameters.	-- [params]\n-- int :from_days_ago = 0\n-- int :duration_days = 28\n\nWITH t AS (\n    SELECT\n        CURRENT_DATE::timestamp - ((:from_days_ago + :duration_days) * (INTERVAL '1 days')) AS period_start,\n        CURRENT_DATE::timestamp - (:from_days_ago * (INTERVAL '1 days')) AS period_end\n),\nread_visits AS (\n    SELECT user_id, SUM(posts_read) AS posts_read\n    FROM user_visits, t\n    WHERE posts_read >= 1\n        AND visited_at > t.period_start\n        AND visited_at < t.period_end\n    GROUP BY user_id\n)\nSELECT\n    CASE\n        WHEN posts_read <= 1 THEN '0001'\n        WHEN posts_read <= 3 THEN '0002 - 0003'\n        WHEN posts_read <= 7 THEN '0004 - 0007'\n        WHEN posts_read <= 15 THEN '0008 - 0015'\n        WHEN posts_read <= 31 THEN '0016 - 0031'\n        WHEN posts_read <= 63 THEN '0032 - 0063'\n        WHEN posts_read <= 127 THEN '0064 - 0127'\n        WHEN posts_read <= 255 THEN '0128 - 0255'\n        WHEN posts_read <= 511 THEN '0256 - 0511'\n        WHEN posts_read <= 1023 THEN '0512 - 1023'\n        WHEN posts_read <= 2047 THEN '1024 - 2047'\n        ELSE '2048+'\n    END AS posts_read_bucket,\n    COUNT(*) AS num_users\nFROM read_visits\nGROUP BY posts_read_bucket\nORDER BY posts_read_bucket\n	-1	\N	f	2026-11-21 23:57:42.257985	2026-11-21 23:57:42.257985
-37	Flags by Type	Number of flags per flag type, split into flags reported by real users and flags raised by automated accounts (system, bots). Accepts a 'days_ago' parameter, defaults to the last 90 days.	-- [params]\n-- int :days_ago = 90\n\nSELECT\n    COALESCE(f.name, 'score_type_' || rs.reviewable_score_type) AS flag_type,\n    -- system and bot accounts have non-positive user ids\n    COUNT(*) FILTER (WHERE rs.user_id > 0) AS reported_by_users,\n    COUNT(*) FILTER (WHERE rs.user_id <= 0) AS automated,\n    COUNT(*) AS total\nFROM reviewable_scores rs\nLEFT JOIN flags f ON f.id = rs.reviewable_score_type\nWHERE rs.created_at >= CURRENT_DATE - CAST(:days_ago AS integer)\nGROUP BY 1\nORDER BY total DESC\n	-1	\N	f	2026-11-21 23:57:42.26066	2026-11-21 23:57:42.26066
-38	Flags Handled by Staff Member	Number of review queue items handled per staff member, useful for recognizing moderation workload. Accepts a 'days_ago' parameter, defaults to the last 90 days.	-- [params]\n-- int :days_ago = 90\n\nSELECT\n    rs.reviewed_by_id AS user_id,\n    COUNT(*) AS flags_handled\nFROM reviewable_scores rs\nJOIN users u ON u.id = rs.reviewed_by_id\nWHERE (u.admin OR u.moderator)\n    AND rs.reviewed_at >= CURRENT_DATE - CAST(:days_ago AS integer)\nGROUP BY rs.reviewed_by_id\nORDER BY flags_handled DESC\nLIMIT 100\n	-1	\N	f	2026-11-21 23:57:42.263349	2026-11-21 23:57:42.263349
-39	Suspended Users Report	Currently suspended users, when they were suspended, until when, by whom and why. Accepts optional 'start_date', 'end_date' and 'suspended_by' parameters.	-- [params]\n-- null date :start_date\n-- null date :end_date\n-- null string :suspended_by\n\nSELECT\n    u.id AS user_id,\n    u.suspended_at,\n    u.suspended_till,\n    COALESCE(staff.username, 'system') AS suspended_by,\n    uh.created_at AS suspension_logged_at,\n    uh.details\nFROM users u\n-- lateral join picks only the most recent suspension record per user\nLEFT JOIN LATERAL (\n    SELECT *\n    FROM user_histories\n    WHERE target_user_id = u.id\n        AND action = 10 -- suspend_user\n    ORDER BY id DESC\n    LIMIT 1\n) uh ON true\nLEFT JOIN users staff\n    ON staff.id = uh.acting_user_id\nWHERE u.suspended_till > CURRENT_TIMESTAMP\n    AND (:start_date IS NULL OR uh.created_at >= :start_date)\n    AND (:end_date IS NULL OR uh.created_at <= :end_date)\n    AND (\n        :suspended_by IS NULL\n        OR ((:suspended_by = 'system' AND staff.username IS NULL) OR staff.username = :suspended_by)\n    )\nORDER BY uh.created_at DESC NULLS LAST\n	-1	\N	f	2026-11-21 23:57:42.26577	2026-11-21 23:57:42.26577
-40	Topics Not in the Site's Primary Language	Recently created topics whose detected language differs from the site's primary language, useful for routing content for translation or moderation. WARNING: requires content localization with locale detection to be enabled (e.g. the content_localization_enabled and ai_translation_enabled site settings); without it topics have no locale recorded and this report will be empty. Accepts 'primary_locale' and 'days_ago' parameters.	-- [params]\n-- string :primary_locale = en\n-- int :days_ago = 30\n\nSELECT\n    t.locale,\n    t.id AS topic_id,\n    t.category_id,\n    t.created_at\nFROM topics t\nWHERE t.locale IS NOT NULL\n    AND t.locale <> ''\n    AND split_part(t.locale, '_', 1) <> split_part(:primary_locale, '_', 1)\n    AND t.created_at >= CURRENT_DATE - CAST(:days_ago AS integer)\n    AND t.deleted_at IS NULL\nORDER BY t.created_at DESC\n	-1	\N	f	2026-11-21 23:57:42.267944	2026-11-21 23:57:42.267944
-41	Posts Not in the Site's Primary Language	Recent posts whose detected language differs from the site's primary language, with a short excerpt. WARNING: requires content localization with locale detection to be enabled (e.g. the content_localization_enabled and ai_translation_enabled site settings); without it posts have no locale recorded and this report will be empty. Accepts 'primary_locale' and 'days_ago' parameters.	-- [params]\n-- string :primary_locale = en\n-- int :days_ago = 30\n\nSELECT\n    p.locale,\n    p.id AS post_id,\n    p.topic_id,\n    LEFT(p.raw, 100) AS excerpt,\n    p.created_at\nFROM posts p\nWHERE p.locale IS NOT NULL\n    AND p.locale <> ''\n    AND split_part(p.locale, '_', 1) <> split_part(:primary_locale, '_', 1)\n    AND p.created_at >= CURRENT_DATE - CAST(:days_ago AS integer)\n    AND p.deleted_at IS NULL\nORDER BY p.created_at DESC\n	-1	\N	f	2026-11-21 23:57:42.270441	2026-11-21 23:57:42.270441
-42	Crawler and Bot Traffic Overview	Buckets recent beacon pageviews by bot-likelihood score from Discourse's built-in crawler detection. Scoring lags live traffic, so the newest pageviews sit in the 'not scored' bucket alongside those that carried no bot signals at all, rather than counting as users. WARNING: requires scoring (hidden site setting experimental_detect_crawler_pageviews); without it, every pageview lands in 'not scored'. Accepts an 'hours' parameter, defaults to the last 24 hours.	-- [params]\n-- int :hours = 24\n\nWITH events AS (\n    SELECT score\n    FROM browser_pageview_events\n    WHERE created_at >= NOW() - (:hours * INTERVAL '1 hour')\n)\nSELECT 'Not scored (pending or no signals)' AS bucket, COUNT(*) FILTER (WHERE score IS NULL) AS pageviews FROM events\nUNION ALL\nSELECT 'Very likely user (under 60)', COUNT(*) FILTER (WHERE score < 60) FROM events\nUNION ALL\nSELECT 'Likely crawler (60+)', COUNT(*) FILTER (WHERE score >= 60) FROM events\n	-1	\N	f	2026-11-21 23:57:42.273182	2026-11-21 23:57:42.273182
-43	Crawler and Bot Traffic Detailed Report	Row-per-IP breakdown of likely bot pageview activity, with the individual signals that drove the score (automated user agent, known crawler network, velocity, session churn, rapid navigation, bad referrer, distributed traffic, no measured interaction). WARNING: requires the improved_crawler_detection upcoming change to be enabled; without it this report will be empty. Accepts 'hours' and 'min_score' parameters.	-- [params]\n-- int :hours = 24\n-- int :min_score = 40\n\nSELECT\n    MAX(e.score) AS max_score,\n    e.session_id,\n    e.ip_address,\n    e.user_id,\n    e.user_agent,\n    e.asn,\n    e.country_code,\n    COUNT(*) AS pageviews,\n    MAX(s.automation_ua_score) AS automation_ua,\n    MAX(s.datacenter_asn_score) AS datacenter_asn,\n    MAX(s.single_request_no_referrer_score) AS single_request_no_referrer,\n    MAX(s.stale_browser_score) AS stale_browser,\n    MAX(s.velocity_score) AS velocity,\n    MAX(s.churn_score) AS churn,\n    MAX(s.rapid_nav_score) AS rapid_nav,\n    MAX(s.referrer_score) AS referrer,\n    MAX(s.distributed_traffic_score) AS distributed_traffic,\n    MAX(s.engagement_score) AS no_engagement,\n    NULLIF(\n        CONCAT_WS(', ',\n            CASE WHEN MAX(s.automation_ua_score) > 0 THEN 'automation UA' END,\n            CASE WHEN MAX(s.datacenter_asn_score) > 0 THEN 'datacenter ASN' END,\n            CASE\n              WHEN MAX(s.single_request_no_referrer_score) = 15\n                THEN 'single direct locale request (+' || MAX(s.single_request_no_referrer_score) || ')'\n              WHEN MAX(s.single_request_no_referrer_score) > 0\n                THEN 'single direct request (+' || MAX(s.single_request_no_referrer_score) || ')'\n            END,\n            CASE WHEN MAX(s.stale_browser_score) > 0 THEN 'stale Chromium (+' || MAX(s.stale_browser_score) || ')' END,\n            CASE WHEN MAX(s.velocity_score) > 0 THEN 'high velocity (+' || MAX(s.velocity_score) || ')' END,\n            CASE WHEN MAX(s.churn_score) > 0 THEN 'session churn (+' || MAX(s.churn_score) || ')' END,\n            CASE WHEN MAX(s.rapid_nav_score) > 0 THEN 'rapid navigation' END,\n            CASE WHEN MAX(s.referrer_score) > 0 THEN 'bad referrer (+' || MAX(s.referrer_score) || ')' END,\n            CASE WHEN MAX(s.distributed_traffic_score) > 0 THEN 'distributed traffic (+' || MAX(s.distributed_traffic_score) || ')' END,\n            CASE WHEN MAX(s.engagement_score) > 0 THEN 'no measured interaction (+' || MAX(s.engagement_score) || ')' END\n        ),\n        ''\n    ) AS reasons\nFROM browser_pageview_events e\nJOIN browser_pageview_event_scores s ON s.event_id = e.id\nWHERE e.created_at >= NOW() - (:hours * INTERVAL '1 hour')\n    AND e.score > :min_score\nGROUP BY e.ip_address, e.user_agent, e.asn, e.country_code, e.user_id, e.session_id\nORDER BY max_score DESC, pageviews DESC\n	-1	\N	f	2026-11-21 23:57:42.276108	2026-11-21 23:57:42.276108
-44	Suspected Automated Traffic by IP and Network	Networks (ASNs) and IPs generating high pageview volume with bot-like session patterns (near 1.0 views per session, rotating user agents, systematic topic harvesting), sorted so a scrape spread across many IPs on one network floats to the top. Accepts a 'days_ago' parameter, defaults to the last 3 days.	-- [params]\n-- int :days_ago = 3\n\nSELECT\n    ip_address,\n    asn,\n    country_code,\n    COUNT(*) AS pageviews,\n    COUNT(DISTINCT session_id) AS sessions,\n    ROUND(COUNT(*)::numeric / NULLIF(COUNT(DISTINCT session_id), 0), 1) AS views_per_session,\n    COUNT(DISTINCT user_agent) AS user_agents,\n    COUNT(DISTINCT topic_id) FILTER (WHERE topic_id IS NOT NULL) AS topics_touched,\n    -- network-wide total, so a scrape spread thin across many IPs\n    -- on one network still sorts to the top\n    SUM(COUNT(*)) OVER (PARTITION BY asn) AS asn_total_pageviews,\n    MIN(created_at) AS first_seen,\n    MAX(created_at) AS last_seen,\n    (array_agg(user_agent ORDER BY created_at DESC))[1] AS sample_user_agent\nFROM browser_pageview_events\nWHERE created_at >= CURRENT_DATE - CAST(:days_ago AS integer)\nGROUP BY ip_address, asn, country_code\nORDER BY asn_total_pageviews DESC, pageviews DESC\nLIMIT 100\n	-1	\N	f	2026-11-21 23:57:42.279119	2026-11-21 23:57:42.279119
-45	Ask AI - Asks over time	Daily Ask AI counts between start_date and end_date, inclusive (UTC). Requires Discourse AI.	-- [params]\n-- date :start_date\n-- date :end_date\n\nWITH daily_asks AS (\n  SELECT asked_at::date AS date, COUNT(*) AS asks\n  FROM ask_ai_logs\n  WHERE asked_at >= :start_date::date\n    AND asked_at < :end_date::date + INTERVAL '1 day'\n    AND ask_outcome IS DISTINCT FROM 4 -- skipped: the reader never requested an answer\n  GROUP BY asked_at::date\n)\nSELECT days.date::date AS date, COALESCE(daily_asks.asks, 0) AS asks\nFROM generate_series(:start_date::date, :end_date::date, INTERVAL '1 day') AS days(date)\nLEFT JOIN daily_asks ON daily_asks.date = days.date::date\nORDER BY days.date\n	-1	\N	f	2026-11-21 23:57:42.281993	2026-11-21 23:57:42.281993
-46	Ask AI - Ask outcomes	Ask AI outcome counts and percentages between start_date and end_date, inclusive (UTC). Requires Discourse AI.	-- [params]\n-- date :start_date\n-- date :end_date\n\nSELECT\n  CASE ask_outcome\n    WHEN 0 THEN 'answered'\n    WHEN 1 THEN 'no_answer'\n    WHEN 2 THEN 'failed'\n    WHEN 3 THEN 'cancelled'\n    ELSE 'pending'\n  END AS outcome,\n  COUNT(*) AS asks,\n  ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (), 1) AS percentage\nFROM ask_ai_logs\nWHERE asked_at >= :start_date::date\n  AND asked_at < :end_date::date + INTERVAL '1 day'\n  AND ask_outcome IS DISTINCT FROM 4 -- skipped: the reader never requested an answer\nGROUP BY ask_outcome\nORDER BY ask_outcome NULLS LAST\n	-1	\N	f	2026-11-21 23:57:42.284466	2026-11-21 23:57:42.284466
-47	Ask AI - Questions included in this report	Questions included in a particular Ask AI report, with their subjects and logged answers. Questions assigned to multiple subjects appear once per subject. Requires Discourse AI.	-- [params]\n-- int :report_id\n\nSELECT\n  subjects.name AS subject,\n  logs.user_id,\n  TO_CHAR(logs.asked_at, 'Mon DD HH24:MI "UTC"') AS asked_at,\n  logs.query,\n  logs.answer_title,\n  logs.answer,\n  CASE logs.ask_outcome\n    WHEN 0 THEN 'answered'\n    WHEN 1 THEN 'no_answer'\n    WHEN 2 THEN 'failed'\n    WHEN 3 THEN 'cancelled'\n    ELSE 'pending'\n  END AS outcome\nFROM ask_ai_reports reports\nJOIN ask_ai_report_subjects subjects ON subjects.ask_ai_report_id = reports.id\nJOIN ask_ai_report_subject_asks memberships ON memberships.ask_ai_report_subject_id = subjects.id\nJOIN ask_ai_logs logs ON logs.id = memberships.ask_ai_log_id\nWHERE reports.id = :report_id\nORDER BY subjects.position, subjects.id, logs.asked_at DESC, logs.id DESC\n	-1	\N	f	2026-11-21 23:57:42.286718	2026-11-21 23:57:42.286718
-48	Ask AI - What users are asking	All Ask AI questions between start_date and end_date, inclusive (UTC), with logged answers. Includes groups excluded from generated reports and is not limited by the report sample size. Requires Discourse AI.	-- [params]\n-- date :start_date\n-- date :end_date\n\nSELECT\n  user_id,\n  TO_CHAR(asked_at, 'Mon DD HH24:MI "UTC"') AS asked_at,\n  query,\n  answer_title,\n  answer,\n  CASE ask_outcome\n    WHEN 0 THEN 'answered'\n    WHEN 1 THEN 'no_answer'\n    WHEN 2 THEN 'failed'\n    WHEN 3 THEN 'cancelled'\n    ELSE 'pending'\n  END AS outcome\nFROM ask_ai_logs\nWHERE asked_at >= :start_date::date\n  AND asked_at < :end_date::date + INTERVAL '1 day'\n  AND ask_outcome IS DISTINCT FROM 4 -- skipped: the reader never requested an answer\nORDER BY ask_ai_logs.asked_at DESC, id DESC\n	-1	\N	f	2026-11-21 23:57:42.289442	2026-11-21 23:57:42.289442
-49	Ask AI - Deferred searches	Searches where Ask AI waited for the reader to request an answer, grouped by reason. Counts searches that stayed deferred and those where the reader requested an answer. Dates are inclusive (UTC). Requires Discourse AI.	-- [params]\n-- date :start_date\n-- date :end_date\n\nSELECT\n  answer_deferred_reason AS reason,\n  COUNT(*) AS deferred_searches,\n  COUNT(*) FILTER (WHERE answer_requested_at IS NULL) AS stayed_deferred,\n  COUNT(*) FILTER (WHERE answer_requested_at IS NOT NULL) AS answers_requested\nFROM ask_ai_logs\nWHERE asked_at >= :start_date::date\n  AND asked_at < :end_date::date + INTERVAL '1 day'\n  AND answer_deferred_reason IS NOT NULL\nGROUP BY answer_deferred_reason\nORDER BY deferred_searches DESC, reason\n	-1	\N	f	2026-11-21 23:57:42.29207	2026-11-21 23:57:42.29207
-50	Ask AI - Cache activity	Cached answers returned and answers evicted by the per-user cache cap. Dates are inclusive (UTC). Requires Discourse AI.	-- [params]\n-- date :start_date\n-- date :end_date\n\nSELECT\n  COUNT(*) FILTER (WHERE cache_hit) AS cache_hits,\n  COALESCE(SUM(cache_evictions), 0) AS cache_evictions\nFROM ask_ai_logs\nWHERE asked_at >= :start_date::date\n  AND asked_at < :end_date::date + INTERVAL '1 day'\n	-1	\N	f	2026-11-21 23:57:42.294539	2026-11-21 23:57:42.294539
